CREATE TABLE `refunds` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `order_id` integer NOT NULL, `group_id` integer, `amount_paisa` integer NOT NULL, `provider` text NOT NULL, `status` text DEFAULT 'pending' NOT NULL, `method` text DEFAULT 'manual' NOT NULL, `note` text DEFAULT '' NOT NULL, `requested_by` text DEFAULT '' NOT NULL, `resolved_by` text, `created_at` integer NOT NULL, `updated_at` integer NOT NULL, FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON UPDATE no action ON DELETE no action, FOREIGN KEY (`group_id`) REFERENCES `order_groups`(`id`) ON UPDATE no action ON DELETE no action);
